import os
from fastapi import APIRouter, Request, HTTPException
from fastapi.responses import HTMLResponse
from fastapi.templating import Jinja2Templates

# New, real, separately-crawlable server-rendered routes for the public/marketing pages that
# used to only exist as JS-toggled panels inside frontend/index.html's single SPA document (see
# window.switchPage / window.scrollToSection / window.showLegalPage there) — Google Search
# Console only ever saw "https://ustadexam.com/" as a result no matter how much content lived
# inside it, since indexing works on distinct URLs, not DOM sections.
#
# Deliberately does NOT touch "/" itself, or anything under /api/ — those keep serving
# index.html (the authenticated app's actual entry point/boot sequence) and the JSON API exactly
# as before. This router is included in main.py BEFORE the final catch-all
# StaticFiles(directory=FRONTEND_DIR) mount at "/", so these explicit paths take priority over it
# for these specific routes only.
router = APIRouter()

TEMPLATES_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "templates")
templates = Jinja2Templates(directory=TEMPLATES_DIR)

SITE_URL = "https://ustadexam.com"


@router.get("/pricing", response_class=HTMLResponse)
async def pricing_page(request: Request):
    return templates.TemplateResponse(request, "pricing.html", {
        "title": "UstadExam Pricing - Free & Pro Plans for Exam Generation & Grading",
        "meta_description": "Compare UstadExam's Free, Student Pro, and Teacher Pro plans. Generate and grade exams with AI — pricing built for individual students and teachers.",
        "canonical_url": f"{SITE_URL}/pricing",
    })


@router.get("/features", response_class=HTMLResponse)
async def features_page(request: Request):
    return templates.TemplateResponse(request, "features.html", {
        "title": "UstadExam Features - AI Exam Generation, Grading & Practice Tools",
        "meta_description": "Explore UstadExam's features: AI exam paper generation, automatic grading with score breakdowns, exam history tracking, weak-topic detection, and timed practice mode.",
        "canonical_url": f"{SITE_URL}/features",
    })


@router.get("/about", response_class=HTMLResponse)
async def about_page(request: Request):
    return templates.TemplateResponse(request, "about.html", {
        "title": "About UstadExam - AI Exam Generation & Grading, Built in Pakistan",
        "meta_description": "UstadExam turns study material into structured, gradable exams using AI. Built by Mujeeb ur Rehman to save teachers hours of exam prep and grading.",
        "canonical_url": f"{SITE_URL}/about",
    })


