# Sidebar order matches index.html's #legal-sidebar exactly (Contact last, disclaimer never
# shown — see LEGAL_PAGES["disclaimer"]["nav_label"] above).
_NAV_ORDER = ["privacy-policy", "terms", "refund-policy", "ai-disclaimer", "academic-integrity",
              "cookie-policy", "copyright-policy", "contact"]
LEGAL_NAV = [(route, LEGAL_PAGES[route]["nav_label"], f"/{route}") for route in _NAV_ORDER]

# Short, purely-functional meta descriptions — spec explicitly says SEO copy doesn't matter for
# these pages, only the real URL + basic tags do.
_META_DESCRIPTIONS = {
    "privacy-policy": "How UstadExam collects, uses, and protects your information.",
    "terms": "The terms and conditions governing use of UstadExam.",
    "refund-policy": "UstadExam's subscription cancellation and refund policy.",
    "ai-disclaimer": "Important limitations of UstadExam's AI-generated questions, answers, and grading.",
    "academic-integrity": "UstadExam's acceptable use and academic integrity policy for students, teachers, and institutions.",
    "cookie-policy": "How UstadExam uses cookies and similar technologies.",
    "copyright-policy": "UstadExam's copyright and content policy for uploaded material.",
    "disclaimer": "General disclaimer covering UstadExam's AI-powered educational tools.",
    "contact": "Contact UstadExam for support, privacy requests, refunds, and other legal matters.",
}


def _register_legal_route(path: str, page: dict) -> None:
    """One route per LEGAL_PAGES entry — a plain loop over a dict can't close over `path`/`page`
    correctly (every route would end up bound to the loop's final values), so each route is
    registered from its own function call instead, where the closure captures that call's own
    arguments as required."""
    @router.get(f"/{path}", response_class=HTMLResponse, name=f"legal_{path}")
    async def _legal_page(request: Request, _path=path, _page=page):
        return templates.TemplateResponse(request, "legal.html", {
            "title": f"{_page['title']} — UstadExam",
            "heading": _page["title"],
            "meta_description": _META_DESCRIPTIONS[_path],
            "canonical_url": f"{SITE_URL}/{_path}",
            "slug": _path,
            "updated": _page["updated"],
            "body_html": _page["html"],
            "legal_nav": LEGAL_NAV,
        })


for _path, _page in LEGAL_PAGES.items():
    _register_legal_route(_path, _page)
